//! Cargo-driven `qmgrprxy.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The module is C, compiled and linked by reactos-link: there is no Rust body.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x6f310000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7fe97000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7fe97000000u64)),
        o => panic!("qmgrprxy-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["dll/win32/qmgrprxy/qmgrprxy_r.o", "engine:pseh", "engine:wine", "import:rpcrt4", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:chkstk", "body", "engine:oldnames"],
        "x86_64" => &["dll/win32/qmgrprxy/qmgrprxy_r.o", "engine:pseh", "engine:wine", "import:rpcrt4", "import:msvcrt", "import:kernel32", "import:ntdll", "body", "engine:oldnames"],
        "aarch64" => &["dll/win32/qmgrprxy/qmgrprxy_r.o", "engine:pseh", "engine:wine", "import:rpcrt4", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:chkstk", "body", "engine:oldnames"],
        _ => unreachable!(),
    };

    Linker::new(target_json)
        .c_from_compile_db("qmgrprxy_shims", &["dll/win32/qmgrprxy/qmgrprxy_i.c", "dll/win32/qmgrprxy/qmgrprxy_p.c", "dll/win32/qmgrprxy/proxy.dlldata.c"])
        .spec2def("dll/win32/qmgrprxy/qmgrprxy.spec", "qmgrprxy.dll")
        .import_lib("dll/win32/rpcrt4/rpcrt4.spec", "rpcrt4.dll", "rpcrt4")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
